//! `classgroup` — exact class number, its factorisation, and the index of the
//! subgroup generated by the small split primes, for the Frobenius field of a
//! prime-order curve (or any negative fundamental discriminant), by the
//! relation method of `crypto::isogeny::class_group_subexp`.
//!
//! Usage:
//!   classgroup --label L (--p P --n N | --disc D) [--bound B] [--half-length M]
//!              [--support k] [--slack bits] [--excess e] [--threads t] [--seed s]
//!              [--sub-bounds 50,163,691,2000] [--euler-bound 10000000]
//!              [--tolerance 0.05] [--max-rounds 6] [--out file.json]
//!
//! Numbers are decimal or 0x-prefixed hex. With --p/--n the discriminant is
//! Δ = t² − 4p, t = p + 1 − n, factored to its fundamental part D_K (the
//! conductor is reported). Output: one JSON object (stdout and/or --out).

use crypto::isogeny::class_group_subexp::{class_order, compute, factor_big, lattice_index, log2_big, SieveParams, Splitting};
use num_bigint::{BigInt, BigUint};
use num_integer::Integer;
use num_traits::{One, Signed};
use std::collections::BTreeMap;
use std::time::Instant;

const MAZUR_ODD: &[u64] = &[3, 5, 7, 11, 13, 17, 19, 37, 43, 67, 163];

fn parse_big(s: &str) -> BigInt {
    let s = s.trim();
    if let Some(h) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        BigInt::parse_bytes(h.as_bytes(), 16).expect("hex integer")
    } else {
        BigInt::parse_bytes(s.as_bytes(), 10).expect("decimal integer")
    }
}

/// Squarefree-kernel factorisation of Δ into f² · D_K by trial division to
/// `trial` plus Pollard–Brent on the cofactor (the cofactor's square part is
/// what matters; a prime cofactor needs no work).
fn fundamental_part(delta: &BigInt) -> (BigInt, BigUint, Vec<(BigUint, u32)>) {
    let mag = delta.magnitude().clone();
    let (factors, complete) = factor_big(&mag);
    assert!(complete, "Δ did not factor completely");
    let mut f = BigUint::one();
    let mut core = BigUint::one();
    for (p, e) in &factors {
        f *= p.pow(e / 2);
        if e % 2 == 1 {
            core *= p;
        }
    }
    // D_K = −core or −4·core according to the residue of −core mod 4
    let mut dk = -BigInt::from(core.clone());
    if dk.mod_floor(&BigInt::from(4)) != BigInt::one() {
        dk *= 4;
        // then f² · D_K = Δ requires f to lose a factor 2
        f /= BigUint::from(2u32);
    }
    debug_assert_eq!(&dk * BigInt::from(&f * &f), *delta);
    (dk, f, factors)
}

fn json_big_list(v: &[(BigUint, u32)]) -> String {
    let ps: Vec<String> = v.iter().map(|(p, _)| p.to_string()).collect();
    let es: Vec<String> = v.iter().map(|(_, e)| e.to_string()).collect();
    format!("\"primes\": [{}], \"exponents\": [{}]", ps.join(", "), es.join(", "))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut opts: BTreeMap<String, String> = BTreeMap::new();
    let mut i = 1;
    while i < args.len() {
        let k = args[i].trim_start_matches("--").to_string();
        let v = args.get(i + 1).cloned().unwrap_or_default();
        opts.insert(k, v);
        i += 2;
    }
    let label = opts.get("label").cloned().unwrap_or_else(|| "disc".into());
    let t0 = Instant::now();
    let (delta, p_opt, n_opt) = if let Some(dstr) = opts.get("disc") {
        (parse_big(dstr), None, None)
    } else {
        let p = parse_big(opts.get("p").expect("--p or --disc"));
        let n = parse_big(opts.get("n").expect("--n"));
        let t = &p + BigInt::one() - &n;
        (&t * &t - BigInt::from(4) * &p, Some(p), Some(n))
    };
    assert!(delta.is_negative(), "discriminant must be negative");
    let (dk, conductor, delta_factors) = fundamental_part(&delta);
    let t_factor = t0.elapsed().as_secs_f64();

    let bits = dk.magnitude().bits();
    let default_bound = {
        let ln = bits as f64 * std::f64::consts::LN_2;
        ((6.0 * ln * ln) as u64).max(1000)
    };
    let bound: u64 = opts.get("bound").map_or(default_bound, |s| s.parse().unwrap());
    let params = SieveParams {
        half_length: opts.get("half-length").map_or(1 << 14, |s| s.parse().unwrap()),
        support: opts.get("support").map_or(10, |s| s.parse().unwrap()),
        slack_bits: opts.get("slack").map_or(26, |s| s.parse().unwrap()),
        excess: opts.get("excess").map_or(64, |s| s.parse().unwrap()),
        threads: opts.get("threads").map_or(4, |s| s.parse().unwrap()),
        seed: opts.get("seed").map_or(1, |s| s.parse().unwrap()),
    };
    let euler_bound: u64 = opts.get("euler-bound").map_or(10_000_000, |s| s.parse().unwrap());
    let tolerance: f64 = opts.get("tolerance").map_or(0.05, |s| s.parse().unwrap());
    let max_rounds: usize = opts.get("max-rounds").map_or(6, |s| s.parse().unwrap());
    let sub_bounds: Vec<u64> = opts
        .get("sub-bounds")
        .map(|s| s.split(',').map(|x| x.trim().parse().unwrap()).collect())
        .unwrap_or_else(|| vec![50, 163, 691, 2000]);

    eprintln!("[{label}] D_K has {bits} bits, conductor {conductor}; factor base bound {bound}; sieving with {} threads", params.threads);
    let t1 = Instant::now();
    let (report, fb, relations) = compute(&dk, bound, &params, tolerance, max_rounds, euler_bound).expect("class group computation");
    let t_relations_and_hnf = t1.elapsed().as_secs_f64();
    eprintln!(
        "[{label}] lattice index has {} bits; analytic log2 h = {:.3}; ratio {:.4}; {} relations from {} products; {} columns eliminated, {} dense",
        report.lattice_index.magnitude().bits(),
        report.analytic_log2_h,
        report.ratio_to_analytic,
        report.relations,
        report.products_sieved,
        report.eliminated_columns,
        report.dense_columns
    );
    let accepted = (report.ratio_to_analytic - 1.0).abs() <= tolerance;
    let h = report.lattice_index.magnitude().clone();

    // factorisation of h and orders of the prime forms
    let t2 = Instant::now();
    let (h_factors, h_complete) = factor_big(&h);
    // genus theory: 2-rank of Cl(D_K) = (number of distinct primes dividing D_K) − 1
    let odd_primes_of_dk = delta_factors.iter().filter(|(p, e)| e % 2 == 1 && **p != BigUint::from(2u32)).count();
    let two_rank = (odd_primes_of_dk + usize::from(dk.is_even())).saturating_sub(1);
    // subgroup indices by bound and the Mazur subset (split primes only, odd)
    let n = fb.len();
    let mut sub_json = Vec::new();
    for &b in &sub_bounds {
        let keep: Vec<bool> = fb.iter().map(|fp| !(fp.p <= b && fp.p > 2 && fp.kind == Splitting::Split)).collect();
        let idx = lattice_index(&relations, n, &keep);
        sub_json.push(format!("\"{}\": {}", b, idx.map_or("null".to_string(), |x| x.to_string())));
    }
    let keep_mazur: Vec<bool> = fb.iter().map(|fp| !(MAZUR_ODD.contains(&fp.p) && fp.kind == Splitting::Split)).collect();
    let idx_mazur = lattice_index(&relations, n, &keep_mazur);
    let mazur_split: Vec<u64> = fb.iter().filter(|fp| MAZUR_ODD.contains(&fp.p) && fp.kind == Splitting::Split).map(|fp| fp.p).collect();
    // all primes (split, ramified, 2) up to each bound, for comparison
    let mut sub_all_json = Vec::new();
    for &b in &sub_bounds {
        let keep: Vec<bool> = fb.iter().map(|fp| fp.p > b).collect();
        let idx = lattice_index(&relations, n, &keep);
        sub_all_json.push(format!("\"{}\": {}", b, idx.map_or("null".to_string(), |x| x.to_string())));
    }
    // orders of the split prime forms up to 2000 (exact when h is fully factored)
    let mut orders = Vec::new();
    let mut smallest_full = 0u64;
    if h_complete {
        for fp in fb.iter().filter(|fp| fp.p <= 2000 && fp.p > 2 && fp.kind == Splitting::Split) {
            let o = class_order(&fp.form, &h, &h_factors);
            if smallest_full == 0 && o == h {
                smallest_full = fp.p;
            }
            orders.push(format!("[{}, {}]", fp.p, o));
        }
    }
    let t_orders = t2.elapsed().as_secs_f64();
    let l1 = report.l1_partial;

    let json = format!(
        "{{\"label\": \"{label}\", \"p\": {}, \"n\": {}, \"Delta\": {}, \"Delta_factorisation\": {{{}}}, \"D_K\": {}, \"D_K_bits\": {bits}, \"conductor\": {conductor}, \
\"bound\": {bound}, \"grh_generating_bound\": {:.0}, \"factor_base\": {n}, \"split\": {}, \"ramified\": {}, \"relations\": {}, \"products_sieved\": {}, \
\"eliminated_columns\": {}, \"dense_columns\": {}, \"h\": {}, \"h_bits\": {}, \"h_log2\": {:.4}, \"analytic_log2_h\": {:.4}, \"l1_partial_euler_bound\": {euler_bound}, \"l1_partial\": {:.6}, \
\"ratio_to_analytic\": {:.5}, \"accepted\": {accepted}, \"h_factorisation\": {{{}}}, \"h_factorisation_complete\": {h_complete}, \"two_rank_genus\": {two_rank}, \
\"index_of_subgroup_by_split_odd_le\": {{{}}}, \"index_of_subgroup_by_all_primes_le\": {{{}}}, \"mazur_split\": [{}], \"index_of_subgroup_by_mazur\": {}, \
\"split_form_orders\": [{}], \"smallest_split_prime_with_full_order\": {smallest_full}, \
\"params\": {{\"half_length\": {}, \"support\": {}, \"slack_bits\": {}, \"excess\": {}, \"threads\": {}, \"seed\": {}, \"tolerance\": {tolerance}}}, \
\"wall_s\": {{\"factor_delta\": {:.3}, \"relations_and_hnf\": {:.3}, \"orders_and_subgroups\": {:.3}, \"total\": {:.3}}}}}",
        p_opt.map_or("null".into(), |x| x.to_string()),
        n_opt.map_or("null".into(), |x| x.to_string()),
        delta,
        json_big_list(&delta_factors),
        dk,
        report.grh_generating_bound,
        report.split_primes,
        report.ramified_primes,
        report.relations,
        report.products_sieved,
        report.eliminated_columns,
        report.dense_columns,
        h,
        h.bits(),
        log2_big(&h),
        report.analytic_log2_h,
        l1,
        report.ratio_to_analytic,
        json_big_list(&h_factors),
        sub_json.join(", "),
        sub_all_json.join(", "),
        mazur_split.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(", "),
        idx_mazur.map_or("null".to_string(), |x| x.to_string()),
        orders.join(", "),
        params.half_length,
        params.support,
        params.slack_bits,
        params.excess,
        params.threads,
        params.seed,
        t_factor,
        t_relations_and_hnf,
        t_orders,
        t0.elapsed().as_secs_f64(),
    );
    println!("{json}");
    if let Some(path) = opts.get("out") {
        std::fs::write(path, format!("{json}\n")).expect("write --out");
    }
}
